-- Deep polish for the D1 keep-left/keep-right family and related island-passing obligations.
START TRANSACTION;
-- D1c -> live sign_code D1c
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Wat betekent dit verkeersbord?', q.question_en = 'What does this traffic sign mean?', q.question_fr = 'Que signifie ce panneau de signalisation ?', q.question_ar = 'ما معنى هذه العلامة المرورية؟', q.explanation_nl = 'Dit verkeersbord verplicht bestuurders links aan te houden. Het bepaalt de rijpositie die op deze weg moet worden gevolgd.', q.explanation_en = 'This traffic sign requires drivers to keep to the left side of the road. It sets the required position on this road.', q.explanation_fr = 'Ce panneau de signalisation oblige les conducteurs a serrer a gauche. Il fixe la position de circulation a respecter sur cette route.', q.explanation_ar = 'تُلزم هذه العلامة المرورية السائقين بالالتزام بالجانب الأيسر من الطريق. وتحدد موضع السير الواجب اتباعه على هذا الطريق.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q01';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Verplichting links aanhouden', c.text_en = 'Keep to the left', c.text_fr = 'Obligation de serrer a gauche', c.text_ar = 'إلزام الإمساك باليسار' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q01' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Verplichting rechts aanhouden', c.text_en = 'Keep to the right', c.text_fr = 'Obligation de serrer a droite', c.text_ar = 'إلزامية الإمساك باليمين' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q01' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Verplichting rechtdoor', c.text_en = 'Mandatory straight ahead', c.text_fr = 'Obligation d aller tout droit', c.text_ar = 'طريق إجباري إلى الأمام' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q01' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Tot welke categorie verkeersborden behoort dit bord?', q.question_en = 'To which category of traffic signs does this sign belong?', q.question_fr = 'A quelle categorie de panneaux appartient ce panneau ?', q.question_ar = 'إلى أي فئة تُصنَّف هذه العلامة المرورية؟', q.explanation_nl = 'Dit is een gebodsbord. Het verplicht bestuurders links aan te houden.', q.explanation_en = 'This is a mandatory sign. It requires drivers to keep to the left.', q.explanation_fr = 'Il s agit d un panneau d obligation. Il oblige les conducteurs a serrer a gauche.', q.explanation_ar = 'هذه العلامة المرورية من علامات الإلزام. وهي تُلزم السائقين بالالتزام بالجانب الأيسر.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q02';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Gebodsborden', c.text_en = 'Mandatory signs', c.text_fr = 'Panneaux d obligation', c.text_ar = 'العلامات الإلزامية' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q02' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Verbodsborden', c.text_en = 'Prohibition signs', c.text_fr = 'Panneaux d interdiction', c.text_ar = 'علامات الحظر' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q02' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Parkeerborden', c.text_en = 'Parking signs', c.text_fr = 'Panneaux de stationnement', c.text_ar = 'علامات الوقوف' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q02' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Wat is het verschil tussen links aanhouden en rechts aanhouden?', q.question_en = 'What is the difference between keeping to the left and keeping to the right?', q.question_fr = 'Quelle est la difference entre serrer a gauche et serrer a droite ?', q.question_ar = 'ما الفرق بين الالتزام بالجانب الأيسر والالتزام بالجانب الأيمن؟', q.explanation_nl = 'Deze twee verkeersborden zijn elkaars spiegelbeeld. Het ene verplicht links aan te houden, het andere rechts.', q.explanation_en = 'These two traffic signs are mirror images. One requires keeping left, while the other requires keeping right.', q.explanation_fr = 'Ces deux panneaux sont en miroir. L un impose de serrer a gauche, l autre de serrer a droite.', q.explanation_ar = 'هاتان العلامتان المرورتان متناظرتان. إحداهما تفرض الالتزام بالجانب الأيسر، والأخرى تفرض الالتزام بالجانب الأيمن.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q03';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Het ene verplicht links aan te houden, het andere rechts.', c.text_en = 'One requires keeping left, while the other requires keeping right.', c.text_fr = 'L un impose de serrer a gauche, l autre de serrer a droite.', c.text_ar = 'إحداهما تفرض الالتزام بالجانب الأيسر، والأخرى تفرض الالتزام بالجانب الأيمن.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q03' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Het ene is voor snelwegen en het andere voor stadsstraten.', c.text_en = 'One is for motorways and the other for urban streets.', c.text_fr = 'L un est reserve aux autoroutes et l autre aux rues urbaines.', c.text_ar = 'إحداهما مخصصة للطرق السريعة والأخرى للشوارع داخل المدينة.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q03' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Het ene verbiedt inhalen en het andere laat het toe.', c.text_en = 'One prohibits overtaking and the other allows it.', c.text_fr = 'L un interdit le depassement et l autre l autorise.', c.text_ar = 'إحداهما تمنع التجاوز والأخرى تسمح به.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q03' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'U rijdt op een weg waar dit bord u verplicht links aan te houden. Mag u tijdelijk naar rechts uitwijken om een openstaand portier te vermijden?', q.question_en = 'You are driving on a road where this sign requires you to keep left. May you temporarily move right to avoid an open car door?', q.question_fr = 'Vous roulez sur une route ou ce panneau vous oblige a serrer a gauche. Pouvez-vous vous deporter temporairement vers la droite pour eviter une portiere ouverte ?', q.question_ar = 'أنت تقود على طريق تُلزمك هذه العلامة المرورية بالالتزام بالجانب الأيسر. هل يمكنك الانحراف مؤقتًا إلى اليمين لتفادي باب سيارة مفتوح؟', q.explanation_nl = 'Je mag tijdelijk uitwijken voor een direct gevaar, maar je dient zo snel mogelijk terug te keren naar de verplichte linkerpositie.', q.explanation_en = 'You may temporarily swerve to avoid an immediate hazard, but you must return to the required left position as soon as possible.', q.explanation_fr = 'Vous pouvez devier temporairement pour eviter un danger immediat, mais vous devez revenir a la position gauche requise des que possible.', q.explanation_ar = 'يمكنك الانحراف مؤقتاً لتجنب خطر فوري، لكن يجب عليك العودة إلى الوضع الأيسر المطلوب في أقرب وقت ممكن.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q04';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Neen, u mag de linkerzijde nooit verlaten.', c.text_en = 'No, you may never leave the left side.', c.text_fr = 'Non, vous ne pouvez jamais quitter le cote gauche.', c.text_ar = 'لا، لا يجوز لك مغادرة الجانب الأيسر مطلقًا.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q04' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Ja, en u mag daarna verder rechts blijven rijden.', c.text_en = 'Yes, and you may continue on the right for the rest of the journey.', c.text_fr = 'Oui, et vous pouvez ensuite continuer a rouler a droite.', c.text_ar = 'نعم، ويمكنك متابعة السير على اليمين بقية الطريق.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q04' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Ja, u mag tijdelijk uitwijken om een onmiddellijk gevaar te vermijden, maar u moet daarna meteen weer links aanhouden.', c.text_en = 'Yes, you may move right to avoid an immediate hazard, but you must return to the left immediately afterwards.', c.text_fr = 'Oui, vous pouvez vous deporter temporairement pour eviter un danger immediat, mais vous devez revenir aussitot a gauche.', c.text_ar = 'نعم، يجوز الانحراف مؤقتًا لتفادي خطر فوري، ثم العودة فورًا إلى الجانب الأيسر.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q04' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Vanaf waar geldt de verplichting van dit verkeersbord?', q.question_en = 'From where does the obligation imposed by this sign apply?', q.question_fr = 'A partir de quel endroit l obligation imposee par ce panneau s applique-t-elle ?', q.question_ar = 'من أي موضع يبدأ الالتزام بهذه العلامة المرورية؟', q.explanation_nl = 'Een gebodsbord geldt voortdurend vanaf de plaatsing tot een ophebbord of het einde van de weg.', q.explanation_en = 'A mandatory sign applies continuously from placement until a cancellation sign or the end of the road.', q.explanation_fr = 'Un panneau d obligation s applique continuellement depuis sa pose jusqu a un panneau d annulation ou la fin de la route.', q.explanation_ar = 'تسري علامة مرورية الإلزام باستمرار من موضعها حتى علامة مرورية إلغاء أو نهاية الطريق.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q05';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Vanaf het punt waar het bord staat tot het einde van de weg of een volgend bord dat de verplichting opheft', c.text_en = 'From the point of the sign until the end of the road or a subsequent sign cancelling the obligation', c.text_fr = 'A partir du panneau jusqu a la fin de la route ou un panneau suivant annulant l obligation', c.text_ar = 'من نقطة العلامة المرورية حتى نهاية الطريق أو علامة مرورية لاحقة تُلغي الالتزام' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q05' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Alleen op de 50 meter na het bord', c.text_en = 'Only for 50 metres after the sign', c.text_fr = 'Seulement dans les 50 metres apres le panneau', c.text_ar = 'فقط على مسافة 50 متراً بعد العلامة المرورية' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q05' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Enkel ter hoogte van het bord zelf', c.text_en = 'Only at the exact location of the sign', c.text_fr = 'Uniquement a l endroit exact du panneau', c.text_ar = 'فقط عند موقع العلامة المرورية نفسه' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q05' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'U rijdt op een weg waar dit bord u verplicht links aan te houden en u wilt een voertuig inhalen. Hoe handelt u?', q.question_en = 'You are driving on a road where this sign requires you to keep left and you want to overtake a vehicle. How do you proceed?', q.question_fr = 'Vous roulez sur une route ou ce panneau vous oblige a serrer a gauche et vous souhaitez depasser un vehicule. Comment procedez-vous ?', q.question_ar = 'أنت تسير على طريق تُلزمك هذه العلامة المرورية بالالتزام بالجانب الأيسر وتريد تجاوز مركبة. كيف تتصرف؟', q.explanation_nl = 'Dit verkeersbord verbiedt inhalen op zich niet, maar u moet na het veilig inhalen opnieuw links aanhouden.', q.explanation_en = 'This traffic sign does not prohibit overtaking in itself, but you must return to the left after completing the manoeuvre safely.', q.explanation_fr = 'Ce panneau n interdit pas le depassement en soi, mais vous devez revenir a gauche apres avoir termine la manoeuvre en toute securite.', q.explanation_ar = 'هذه العلامة المرورية لا تمنع التجاوز بحد ذاته، لكن يجب عليك العودة إلى الجانب الأيسر بعد إتمامه بأمان.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q06';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Inhalen is verboden op wegen met dit bord.', c.text_en = 'Overtaking is forbidden on roads with this sign.', c.text_fr = 'Le depassement est interdit sur les routes ou ce panneau est present.', c.text_ar = 'التجاوز ممنوع على الطرق التي تحمل هذه العلامة المرورية.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q06' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'U mag inhalen als dat veilig kan, maar u moet daarna opnieuw links aanhouden.', c.text_en = 'You may overtake if it is safe, but you must return to the left afterwards.', c.text_fr = 'Vous pouvez depasser si cela peut se faire en securite, mais vous devez ensuite revenir a gauche.', c.text_ar = 'يمكنك التجاوز إذا كان ذلك آمنًا، على أن تعود إلى الجانب الأيسر بعده.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q06' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'U mag altijd rechts inhalen, ongeacht dit bord.', c.text_en = 'You may always overtake on the right regardless of the sign.', c.text_fr = 'Vous pouvez toujours depasser par la droite, quelle que soit la signalisation.', c.text_ar = 'يمكنك دائمًا التجاوز من اليمين مهما كانت العلامة.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q06' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Op een weg waar dit bord u verplicht links aan te houden, rijdt u rechts omdat de linkerkant natter is. Is dat toegelaten?', q.question_en = 'On a road where this sign requires you to keep left, you are riding on the right because the left side is wetter. Is that allowed?', q.question_fr = 'Sur une route ou ce panneau vous oblige a serrer a gauche, vous roulez a droite parce que le cote gauche est plus mouille. Est-ce autorise ?', q.question_ar = 'على طريق تُلزمك هذه العلامة المرورية بالالتزام بالجانب الأيسر، تسير على اليمين لأن الجانب الأيسر أكثر بللًا. هل هذا مسموح؟', q.explanation_nl = 'Dit verkeersbord voorziet geen uitzondering vanwege de toestand van het wegdek. Verminder uw snelheid en blijf links aanhouden.', q.explanation_en = 'This traffic sign makes no exception for road-surface conditions. Slow down and continue keeping to the left.', q.explanation_fr = 'Ce panneau ne prevoit aucune exception liee a l etat de la chaussee. Ralentissez et restez a gauche.', q.explanation_ar = 'هذه العلامة المرورية لا تنص على استثناء بسبب حالة سطح الطريق. خفف السرعة وواصل السير على الجانب الأيسر.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q07';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Neen, u moet links aanhouden en een nat wegdek is geen wettelijke uitzondering.', c.text_en = 'No, you must keep left, and a wet surface is not a legal exception.', c.text_fr = 'Non, vous devez serrer a gauche et une chaussee mouillee ne constitue pas une exception legale.', c.text_ar = 'لا، يجب عليك الالتزام بالجانب الأيسر، وبلل الطريق ليس استثناءً قانونيًا.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q07' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Ja, als de linkerkant natter is mag u rechts rijden.', c.text_en = 'Yes, if the left side is wetter you may ride on the right.', c.text_fr = 'Oui, si le cote gauche est plus mouille, vous pouvez rouler a droite.', c.text_ar = 'نعم، إذا كان الجانب الأيسر مبللًا يمكنك السير على اليمين.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q07' AND c.display_order = 2;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'De weg is volledig leeg. Mag u rechts rijden ook al verplicht dit bord u links aan te houden?', q.question_en = 'The road is completely empty. May you ride on the right even though this sign requires you to keep left?', q.question_fr = 'La route est completement vide. Pouvez-vous rouler a droite alors que ce panneau vous oblige a serrer a gauche ?', q.question_ar = 'الطريق خالٍ تمامًا. هل يمكنك السير على اليمين رغم أن هذه العلامة المرورية تُلزمك بالالتزام بالجانب الأيسر؟', q.explanation_nl = 'Dit verkeersbord hangt niet af van de aanwezigheid van andere voertuigen. De verplichting om links aan te houden blijft altijd gelden.', q.explanation_en = 'This traffic sign does not depend on the presence of other vehicles. The obligation to keep left remains in force at all times.', q.explanation_fr = 'Ce panneau ne depend pas de la presence d autres vehicules. L obligation de serrer a gauche reste toujours en vigueur.', q.explanation_ar = 'هذه العلامة المرورية لا ترتبط بوجود مركبات أخرى. يبقى الالتزام بالجانب الأيسر قائمًا دائمًا.' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q08';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Neen, de verplichting geldt ongeacht of er ander verkeer is', c.text_en = 'No, the obligation applies regardless of whether there is other traffic', c.text_fr = 'Non, l obligation s applique que soit il y a d autre trafic ou non', c.text_ar = 'لا، الالتزام ينطبق بصرف النظر عن وجود مرور آخر' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q08' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Ja, bij afwezigheid van verkeer maakt het niet uit op welke kant u rijdt', c.text_en = 'Yes, in the absence of traffic it does not matter which side you ride on', c.text_fr = 'Oui, en l absence de trafic peu importe de quel cote vous roulez', c.text_ar = 'نعم، في غياب المرور لا يهم أي جانب تسير فيه' WHERE rs.sign_code = 'D1c' AND q.question_ref = 'D1c_Q08' AND c.display_order = 2;

-- D1d -> live sign_code D1d
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Wat betekent dit verkeersbord?', q.question_en = 'What does this traffic sign mean?', q.question_fr = 'Que signifie ce panneau de signalisation ?', q.question_ar = 'ما معنى هذه العلامة المرورية؟', q.explanation_nl = 'Dit bord verplicht alle bestuurders om rechts aan te houden op de rijbaan.', q.explanation_en = 'This sign requires all drivers to keep to the right side of the road.', q.explanation_fr = 'Ce panneau oblige les conducteurs a serrer a droite de la chaussee.', q.explanation_ar = 'تُلزم هذه العلامة المرورية جميع السائقين بالالتزام بالجانب الأيمن من الطريق.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q01';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Verplichting rechts aanhouden', c.text_en = 'Keep to the right', c.text_fr = 'Obligation de serrer a droite', c.text_ar = 'إلزام الإمساك باليمين' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q01' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Verplichting links aanhouden', c.text_en = 'Keep to the left', c.text_fr = 'Obligation de serrer a gauche', c.text_ar = 'إلزام الإمساك باليسار' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q01' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Verplichting links afslaan', c.text_en = 'Mandatory left turn', c.text_fr = 'Obligation de tourner a gauche', c.text_ar = 'إلزامية القيادة باتجاه اليسار' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q01' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Tot welke categorie verkeersborden behoort dit bord?', q.question_en = 'To which category of traffic signs does this sign belong?', q.question_fr = 'A quelle categorie de panneaux de signalisation appartient ce panneau ?', q.question_ar = 'إلى أي فئة تُصنَّف هذه العلامة المرورية؟', q.explanation_nl = 'Dit is een gebodsbord. Het verplicht bestuurders rechts aan te houden.', q.explanation_en = 'This is a mandatory sign. It requires drivers to keep to the right.', q.explanation_fr = 'Il s agit d un panneau d obligation. Il oblige les conducteurs a serrer a droite.', q.explanation_ar = 'هذه العلامة المرورية من علامات الإلزام. وهي تُلزم السائقين بالالتزام بالجانب الأيمن.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q02';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Gebodsborden', c.text_en = 'Mandatory signs', c.text_fr = 'Panneaux d''obligation', c.text_ar = 'العلامات الإلزامية' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q02' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Verbodsborden', c.text_en = 'Prohibition signs', c.text_fr = 'Panneaux d''interdiction', c.text_ar = 'علامات الحظر' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q02' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Parkeerborden', c.text_en = 'Parking signs', c.text_fr = 'Panneaux de stationnement', c.text_ar = 'علامات الوقوف' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q02' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Wat verplicht dit bord u te doen op de rijbaan?', q.question_en = 'What does this sign require you to do on the road?', q.question_fr = 'Qu''est-ce que ce panneau vous oblige a faire sur la chaussee ?', q.question_ar = 'ماذا تُلزمك هذه العلامة المرورية بفعله على الطريق؟', q.explanation_nl = 'Dit verkeersbord legt de verplichting op om rechts aan te houden. Alle weggebruikers moeten dit naleven.', q.explanation_en = 'This traffic sign imposes the obligation to keep to the right. All road users must comply with it.', q.explanation_fr = 'Ce panneau impose l obligation de serrer a droite. Tous les usagers de la route doivent la respecter.', q.explanation_ar = 'تفرض هذه العلامة المرورية الالتزام بالجانب الأيمن من الطريق. ويجب على جميع مستخدمي الطريق احترام هذا الالتزام.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q03';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Rechts aanhouden langs de rechterrand van de rijbaan', c.text_en = 'Keep to the right side of the road', c.text_fr = 'Serrer sur la droite de la chaussee', c.text_ar = 'الالتزام بالجانب الأيمن من الطريق' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q03' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Vaart minderen tot 30 km/u', c.text_en = 'Reduce speed to 30 km/h', c.text_fr = 'Reduire la vitesse a 30 km/h', c.text_ar = 'تخفيض السرعة إلى 30 كم/س' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q03' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Links aanhouden om tegenliggers voorrang te verlenen', c.text_en = 'Keep to the left to give way to oncoming vehicles', c.text_fr = 'Serrer a gauche pour ceder le passage aux vehicules venant en sens inverse', c.text_ar = 'الالتزام بالجانب الأيسر لإفساح المجال لمركبات مقابلة' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q03' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'U rijdt op een weg waar dit bord u verplicht rechts aan te houden. Een geparkeerd voertuig blokkeert gedeeltelijk de rechterkant. Wat moet u doen?', q.question_en = 'You are driving on a road where this sign requires you to keep right. A parked vehicle partly blocks the right side. What must you do?', q.question_fr = 'Vous roulez sur une route ou ce panneau vous oblige a serrer a droite. Un vehicule stationne bloque partiellement le cote droit. Que devez-vous faire ?', q.question_ar = 'أنت تسير على طريق تُلزمك هذه العلامة المرورية بالالتزام بالجانب الأيمن. مركبة متوقفة تسد جزئيًا الجهة اليمنى. ماذا يجب عليك فعله؟', q.explanation_nl = 'Dit verkeersbord verplicht u rechts aan te houden. Bij een tijdelijke hindernis rijdt u er voorbij terwijl u zo ver mogelijk rechts blijft en daarna meteen terugkeert naar uw juiste positie.', q.explanation_en = 'This traffic sign requires you to keep right. If there is a temporary obstruction, pass it while staying as far right as possible and return immediately to the correct position.', q.explanation_fr = 'Ce panneau vous oblige a serrer a droite. En presence d une obstruction temporaire, vous la contournez en restant le plus a droite possible, puis vous reprenez immediatement votre bonne position.', q.explanation_ar = 'تُلزمك هذه العلامة المرورية بالالتزام باليمين. عند وجود عائق مؤقت، تمر بمحاذاته مع البقاء أقصى اليمين قدر الإمكان ثم تعود فورًا إلى موضعك الصحيح.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q04';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Zo dicht mogelijk rechts passeren en daarna direct terug rechts blijven rijden', c.text_en = 'Pass as far right as possible and immediately return to the right side', c.text_fr = 'Passer en restant le plus a droite possible et reprendre immediatement votre position droite', c.text_ar = 'المرور بأقصى ما يمكن نحو اليمين والعودة الفورية إلى وضع اليمين' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q04' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Tijdelijk naar links rijden totdat u het voertuig gepasseerd bent', c.text_en = 'Drive temporarily on the left side until you have passed the vehicle', c.text_fr = 'Rouler temporairement a gauche jusqu''a ce que vous ayez depasse le vehicule', c.text_ar = 'القيادة مؤقتاً على الجانب الأيسر حتى تتجاوز المركبة' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q04' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Stoppen en wachten tot het voertuig wegrijdt', c.text_en = 'Stop and wait until the vehicle moves', c.text_fr = 'Vous arreter et attendre que le vehicule parte', c.text_ar = 'التوقف والانتظار حتى تغادر المركبة' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q04' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Een tegenligger rijdt in het midden van de rijbaan terwijl dit bord aanwezig is. Wat moet u doen?', q.question_en = 'An oncoming vehicle is driving in the middle of the road while this sign is present. What must you do?', q.question_fr = 'Un vehicule venant en sens inverse roule au milieu de la chaussee alors que ce panneau est present. Que devez-vous faire ?', q.question_ar = 'مركبة قادمة تسير في وسط الطريق، وهذه العلامة المرورية موجودة. ماذا يجب عليك فعله؟', q.explanation_nl = 'Dit bord verplicht u wettelijk rechts aan te houden. Behoud uw juiste positie en waarschuw de tegenligger indien nodig.', q.explanation_en = 'This sign legally requires you to keep to the right. Maintain your correct position and warn the oncoming driver if necessary.', q.explanation_fr = 'Ce panneau vous oblige legalement a serrer a droite. Gardez votre bonne position et avertissez l autre conducteur si necessaire.', q.explanation_ar = 'يفرض هذا الالتزام عليك السير على الجانب الأيمن. حافظ على موضعك الصحيح، ونبّه السائق القادم عند الحاجة.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q05';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Rechts aanhouden en indien nodig de tegenligger waarschuwen met knipperlichten', c.text_en = 'Keep right and warn the oncoming driver with flashing lights if necessary', c.text_fr = 'Serrer a droite et avertir le conducteur venant en sens inverse par appels de phares si necessaire', c.text_ar = 'الالتزام باليمين وتحذير السائق القادم بالأضواء الوامضة عند الحاجة' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q05' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Naar links uitwijken om een botsing te voorkomen', c.text_en = 'Move to the left to avoid a collision', c.text_fr = 'Devier a gauche pour eviter une collision', c.text_ar = 'الانحراف إلى اليسار لتجنب التصادم' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q05' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Stoppen en wachten tot de tegenligger rechts rijdt', c.text_en = 'Stop and wait until the oncoming vehicle drives right', c.text_fr = 'Vous arreter et attendre que le vehicule venant en sens inverse se deplace a droite', c.text_ar = 'التوقف والانتظار حتى يتحول السائق القادم إلى اليمين' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q05' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'U rijdt op een smalle weg waar dit bord u verplicht rechts aan te houden, en u wilt in een bocht iets naar links uitwijken voor meer comfort. Is dat toegestaan?', q.question_en = 'You are on a narrow road where this sign requires you to keep right, and you want to move slightly left in a bend for more comfort. Is this allowed?', q.question_fr = 'Vous roulez sur une route etroite ou ce panneau vous oblige a serrer a droite, et vous voulez vous deporter legerement a gauche dans un virage pour plus de confort. Est-ce autorise ?', q.question_ar = 'أنت على طريق ضيق تُلزمك هذه العلامة المرورية بالالتزام بالجانب الأيمن، وتريد الانزياح قليلًا إلى اليسار داخل منعطف لمزيد من الراحة. هل هذا مسموح؟', q.explanation_nl = 'Deze verplichting blijft ook in bochten gelden. U moet rechts aanhouden, ongeacht de vorm van de bocht.', q.explanation_en = 'The obligation remains in force even in bends. You must keep to the right regardless of the shape of the bend.', q.explanation_fr = 'Cette obligation reste valable meme dans les virages. Vous devez serrer a droite quelle que soit la forme du virage.', q.explanation_ar = 'يبقى هذا الالتزام ساريًا حتى داخل المنعطفات. يجب عليك الالتزام بالجانب الأيمن بغض النظر عن شكل المنعطف.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q06';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Neen, dit bord verplicht u ook in bochten rechts aan te houden.', c.text_en = 'No, this sign requires you to keep right even in bends.', c.text_fr = 'Non, ce panneau vous oblige a serrer a droite meme dans les virages.', c.text_ar = 'لا، تُلزمك هذه العلامة المرورية بالالتزام بالجانب الأيمن حتى داخل المنعطفات.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q06' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Ja, in bochten mag u uw lijn aanpassen voor meer stabiliteit.', c.text_en = 'Yes, in bends you may adjust your line for more stability.', c.text_fr = 'Oui, dans un virage vous pouvez modifier votre trajectoire pour plus de stabilite.', c.text_ar = 'نعم، في المنعطفات يمكنك تعديل خط السير لمزيد من الثبات.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q06' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Ja, zolang er geen tegenligger zichtbaar is.', c.text_en = 'Yes, as long as no oncoming traffic is visible.', c.text_fr = 'Oui, tant qu aucun vehicule n arrive en sens inverse.', c.text_ar = 'نعم، إذا لم يظهر مرور قادم يكون ذلك مسموحًا.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q06' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Dit bord staat voor u, en de rechterkant van de weg is tijdelijk versmald door werken. Mag u in het midden van de rijbaan rijden?', q.question_en = 'This sign is ahead of you, and the right side of the road is temporarily narrowed by roadworks. May you drive in the middle of the lane?', q.question_fr = 'Ce panneau se trouve devant vous et le cote droit de la route est temporairement retreci par des travaux. Pouvez-vous rouler au milieu de la chaussee ?', q.question_ar = 'هذه العلامة المرورية أمامك، والجانب الأيمن من الطريق ضاق مؤقتًا بسبب الأشغال. هل يمكنك السير في وسط المسار؟', q.explanation_nl = 'Wegwerken vormen geen uitzondering op deze verplichting. Blijf rechts aanhouden binnen de beschikbare ruimte.', q.explanation_en = 'Roadworks do not create an exception to this obligation. Continue keeping to the right within the available space.', q.explanation_fr = 'Les travaux ne constituent pas une exception a cette obligation. Continuez a serrer a droite dans l espace disponible.', q.explanation_ar = 'لا تُنشئ أشغال الطريق استثناءً من هذا الالتزام. تابع السير على اليمين ضمن المساحة المتاحة.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q07';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Neen, u moet binnen de beschikbare ruimte rechts blijven aanhouden.', c.text_en = 'No, you must continue keeping to the right within the available space.', c.text_fr = 'Non, vous devez continuer a serrer a droite dans l espace disponible.', c.text_ar = 'لا، يجب عليك الاستمرار في الالتزام باليمين ضمن المساحة المتاحة.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q07' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Ja, wegwerken schorsen dit bord tijdelijk.', c.text_en = 'Yes, roadworks temporarily suspend this sign.', c.text_fr = 'Oui, les travaux suspendent temporairement ce panneau.', c.text_ar = 'نعم، الأشغال توقف مفعول هذه العلامة المرورية مؤقتًا.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q07' AND c.display_order = 2;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'U nadert een ruime bocht en dit bord verplicht u rechts aan te houden. Mag u voor meer comfort dichter naar het midden van de weg rijden?', q.question_en = 'You are approaching a wide bend and this sign requires you to keep to the right. May you move closer to the middle of the road for comfort?', q.question_fr = 'Vous approchez d un large virage et ce panneau vous oblige a serrer a droite. Pouvez-vous vous rapprocher du milieu de la route pour plus de confort ?', q.question_ar = 'أنت تقترب من منعطف واسع وهذه العلامة المرورية تُلزمك بالالتزام بالجانب الأيمن. هل يمكنك الاقتراب من وسط الطريق لمزيد من الراحة؟', q.explanation_nl = 'Dit bord kent geen uitzondering voor bochten. Ook in een ruime bocht moet u rechts aanhouden.', q.explanation_en = 'This sign makes no exception for bends. Even in a wide bend, you must keep to the right.', q.explanation_fr = 'Ce panneau ne prevoit aucune exception pour les virages. Meme dans un large virage, vous devez serrer a droite.', q.explanation_ar = 'لا يوجد في هذه العلامة أي استثناء خاص بالمنعطفات. حتى في المنعطفات الواسعة يجب الالتزام بالجانب الأيمن.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q08';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Neen, dit bord verplicht u rechts aan te houden ongeacht de bocht of het rijcomfort.', c.text_en = 'No, this sign requires you to keep to the right regardless of the bend or your comfort.', c.text_fr = 'Non, ce panneau vous oblige a serrer a droite quelle que soit la forme du virage ou votre confort.', c.text_ar = 'لا، تُلزمك هذه العلامة المرورية بالالتزام بالجانب الأيمن مهما كان شكل المنعطف أو مستوى الراحة.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q08' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Ja, in een ruime bocht mag u wat meer naar het midden rijden als dat comfortabeler aanvoelt.', c.text_en = 'Yes, in a wide bend you may move slightly toward the middle if it feels more comfortable.', c.text_fr = 'Oui, dans un large virage vous pouvez vous rapprocher un peu du centre si cela vous semble plus confortable.', c.text_ar = 'نعم، في المنعطفات الواسعة يمكنك الاقتراب قليلًا من الوسط إذا شعرت أن ذلك أريح.' WHERE rs.sign_code = 'D1d' AND q.question_ref = 'D1d_Q08' AND c.display_order = 2;

COMMIT;
